package whiteboardrender

import (
	"archive/zip"
	"bytes"
	"context"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"image"
	"image/png"
	"io/fs"
	"math"
	"os"
	"strings"
	"testing"
	"time"

	yjs "github.com/antst/go-yjs/crdt"
)

// Browser fixture data is generated by the pinned editor in
// test/e2e/previeworacle. Testing the production renderer here catches
// differences between the original qualification program and packaged code.
//
//nolint:gocyclo // Each fixture shares one decoder, source and two independent image comparisons.
func TestPackagedRendererMatchesSavedBrowserCorpus(t *testing.T) {
	fixtureFS := browserFixtures(t)
	fixtures, err := fs.Glob(fixtureFS, "*.json")
	if err != nil || len(fixtures) == 0 {
		t.Fatalf("no browser corpus: %v", err)
	}
	completed := 0
	for _, file := range fixtures {
		var f struct {
			Mode           string
			Snapshot       []byte
			Assets         map[string]string
			Order          []string
			Source         [2]int
			Outlines       map[string][]vec
			LabelPositions map[string]vec
			Outputs        []struct {
				Width, Height  int
				PNG, DirectPNG []byte
			}
		}
		data, err := fs.ReadFile(fixtureFS, file)
		if err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(data, &f); err != nil || len(f.Outputs) != 2 || len(f.Snapshot) == 0 {
			t.Fatalf("incomplete oracle fixture %s: %v", file, err)
		}
		t.Run(file, func(t *testing.T) {
			doc := yjs.NewDoc("oracle")
			defer doc.Destroy()
			if err := yjs.ApplyUpdateV2(doc, f.Snapshot, nil); err != nil {
				t.Fatal(err)
			}
			load := func(_ context.Context, locator string, _ int64) (string, []byte, error) {
				if raw, ok := f.Assets[locator]; ok {
					if strings.HasPrefix(raw, "<svg") {
						return "image/svg+xml", []byte(raw), nil
					}
					head, data, ok := strings.Cut(raw, ";base64,")
					if !ok {
						return "", nil, fmt.Errorf("invalid oracle asset")
					}
					body, err := base64.StdEncoding.DecodeString(data)
					return strings.TrimPrefix(head, "data:"), body, err
				}
				return "", nil, fs.ErrNotExist
			}
			// Coverage and race instrumentation change relative timing. The
			// production deadline is measured on the normal Render entrypoint.
			ctx, cancel := context.WithTimeout(t.Context(), 25*time.Second)
			defer cancel()
			img, err := render(ctx, doc, load, f.Outputs[0].Width, f.Outputs[0].Height)
			if f.Mode == "missing-index" {
				if err == nil || img.Full != nil || img.Card != nil {
					t.Fatal("missing index must fail closed")
				}
				completed++
				return
			}
			if err != nil {
				t.Fatal(err)
			}
			if len(f.Outlines) != 0 {
				checkStrokeOutlines(t, savedElements(doc), f.Outlines)
			}
			if len(f.LabelPositions) != 0 {
				items := savedElements(doc)
				checkLabelPositions(t, items, f.LabelPositions)
				frames, labels := structuralElements(items)
				ids := make(map[string]bool, len(items))
				for _, e := range items {
					ids[e.ID] = true
				}
				_, _, w, h := view(items, frames, labels, ids)
				if [2]int{w, h} != f.Source {
					t.Fatalf("export framing %dx%d, browser %v", w, h, f.Source)
				}
			}
			dense := len(f.Order) > 40
			for i, serialized := range [][]byte{img.Full, img.Card} {
				want := f.Outputs[i].PNG
				if dense {
					want = f.Outputs[i].DirectPNG
				}
				gotImage := readCorpusPNG(t, serialized)
				wantImage := readCorpusPNG(t, want)
				fraction, mean := compareRendered(t, gotImage, wantImage)
				t.Logf("PNG %v: %.2f%% of painted pixels above threshold; mean delta %.2f", gotImage.Bounds(), 100*fraction, mean)
				if dense && (fraction > .20 || mean > 12) || !dense && (fraction > .08 || mean > 6) {
					t.Fatalf("packaged renderer exceeded agreed visual tolerance for %v", gotImage.Bounds())
				}
			}
			completed++
		})
	}
	if completed < 15 {
		t.Fatalf("only %d fixtures; not the pinned corpus", completed)
	}
}

func checkLabelPositions(t *testing.T, items []savedElement, expected map[string]vec) {
	t.Helper()
	_, labels := structuralElements(items)
	for _, arrow := range items {
		if want, ok := expected[arrow.ID]; ok {
			label := arrowLabel(arrow, labels[arrow.ID])
			if math.Hypot(label.X-want[0], label.Y-want[1]) > .75 {
				t.Fatalf("label for %s at (%g,%g), browser %v", arrow.ID, label.X, label.Y, want)
			}
		}
	}
}

func checkStrokeOutlines(t *testing.T, items []savedElement, expected map[string][]vec) {
	t.Helper()
	matched := 0
	for _, element := range items {
		want, ok := expected[element.ID]
		if !ok {
			continue
		}
		got := freehandOutline(element)
		if len(want) != len(got) {
			t.Fatalf("stroke %q: %d outline points, want %d", element.ID, len(got), len(want))
		}
		for i := range want {
			if math.Abs(got[i][0]-want[i][0]) > 1e-9 || math.Abs(got[i][1]-want[i][1]) > 1e-9 {
				t.Fatalf("stroke %q outline point %d: %v, want %v", element.ID, i, got[i], want[i])
			}
		}
		matched++
	}
	if matched != len(expected) {
		t.Fatalf("%d strokes found, want %d", matched, len(expected))
	}
}

func browserFixtures(t *testing.T) fs.FS {
	t.Helper()
	if dir := os.Getenv("COLLAB_PREVIEW_ORACLE_DIR"); dir != "" {
		return os.DirFS(dir)
	}
	corpus, err := zip.OpenReader("testdata/browser-corpus.zip")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		if err := corpus.Close(); err != nil {
			t.Error(err)
		}
	})
	return corpus
}

func readCorpusPNG(t *testing.T, raster []byte) image.Image {
	t.Helper()
	im, err := png.Decode(bytes.NewReader(raster))
	if err != nil {
		t.Fatal(err)
	}
	return im
}

func compareRendered(t *testing.T, got, want image.Image) (fraction, mean float64) {
	t.Helper()
	rect := want.Bounds()
	if got.Bounds() != rect {
		t.Fatalf("different size: got %v, want %v", got.Bounds(), rect)
	}
	var diff, total, painted int
	for y := rect.Min.Y; y < rect.Max.Y; y++ {
		for x := rect.Min.X; x < rect.Max.X; x++ {
			gr, gg, gb, ga := got.At(x, y).RGBA()
			wr, wg, wb, wa := want.At(x, y).RGBA()
			if ga == 0 && wa == 0 {
				continue
			}
			painted++
			delta := func(a, b uint32) int { return int((max(a, b) - min(a, b)) >> 8) }
			r, g, b, a := delta(gr, wr), delta(gg, wg), delta(gb, wb), delta(ga, wa)
			total += r + g + b + a
			if max(r, g, b, a) >= 32 {
				diff++
			}
		}
	}
	if painted == 0 {
		return 0, 0
	}
	return float64(diff) / float64(painted), float64(total) / float64(4*painted)
}
